bcad_i = (b_r*c_i - b_i*c_r)-(a_r*d_i-a_i*d_r);

// mu*c^(-1)
q3 = bcad_r*c_inv_r - bcad_i*c_inv_i;
q4 = bcad_r*c_inv_i - bcad_i*c_inv_r;

q1 = ac_r;
